#!/usr/bin/env bash
# Writes gitignored LocalAPI.xcconfig for Debug iOS builds. Do not commit.
set -euo pipefail
MOBILE_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT_XC="$MOBILE_ROOT/Rollspot/Config/LocalAPI.xcconfig"
OUT_TXT="$MOBILE_ROOT/Rollspot/Config/LocalAPIBaseURL.txt"

URL="${1:-}"
if [ -z "$URL" ]; then
  echo "Usage: $0 <API base URL>" >&2
  echo "Example: $0 http://192.168.1.10:8787" >&2
  echo "Example: $0 https://abc-123.trycloudflare.com" >&2
  exit 1
fi

case "$URL" in
  http://*|https://*) ;;
  *) URL="http://${URL}" ;;
esac

cat >"$OUT_XC" <<EOF
// Generated by set-ios-api-base-url.sh — gitignored, do not commit.
ROLLSPOT_API_BASE_URL = $URL
EOF
printf '%s\n' "$URL" >"$OUT_TXT"
echo "Wrote $OUT_XC → $URL"
echo "Clean build in Xcode (⇧⌘K), then Run. Console should print: [Rollspot] API base URL: $URL"
